const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const icon = (name) => `<svg class="icon" viewBox="0 0 24 24" fill="none" aria-hidden="true">${ICONS[name]}</svg>`;
const brand = (compact = false) =>
  `<div class="brand-mark ${compact ? 'compact' : ''}" aria-label="옷깃"><span class="brand-name">옷깃</span><span class="brand-stitch" aria-hidden="true"><i></i><i></i></span></div>`;
const button = (children, { act = '', variant = 'primary', cls = '', data = '' } = {}) =>
  `<button class="button ${variant} ${cls}" data-act="${act}" ${data}>${children}</button>`;
const topbar = (title, backAct, action) => `
  <header class="topbar">
    <button class="icon-button" data-act="${backAct}" aria-label="뒤로 가기">${icon('arrow')}</button>
    <span class="topbar-title">${esc(title)}</span>
    <div class="topbar-action">${action}</div>
  </header>`;
const bottomNav = (active) => `
  <nav class="bottom-nav" aria-label="주요 메뉴">
    ${[
      { id: 'today', label: '오늘의 인연', icon: 'home' },
      { id: 'chat', label: '대화', icon: 'chat' },
      { id: 'me', label: '내 프로필', icon: 'person' },
    ].map((n) => `<button class="${active === n.id ? 'active' : ''}" data-act="go:${n.id}">${icon(n.icon)}<span>${n.label}</span></button>`).join('')}
  </nav>`;

