const SCREENS = { welcome, onboarding, today, profile, match, chat, me };
const root = document.getElementById('root');

function render() {
  root.innerHTML = SCREENS[state.screen]();
}

function go(screen) {
  if (screen === 'onboarding') state.step = 1;
  state.screen = screen;
  render();
  window.scrollTo(0, 0);
}

function sendMessage() {
  const text = state.draft.trim();
  if (!text) return;
  state.sent.push(text);
  state.draft = '';
  render();
  document.getElementById('chat-input')?.focus();
}

root.addEventListener('click', (e) => {
  const el = e.target.closest('[data-act]');
  if (!el) return;
  const [cmd, arg] = el.dataset.act.split(/:(.*)/s);
  if (cmd === 'go') go(arg);
  else if (cmd === 'role') { state.role = arg; render(); }
  else if (cmd === 'meet') { state.wantToMeet = arg; render(); }
  else if (cmd === 'step') {
    if (arg === 'prev') state.step -= 1;
    else if (state.step < 3) state.step += 1;
    else return go('today');
    render();
  } else if (cmd === 'pick') { state.selected = Number(arg); render(); }
  else if (cmd === 'suggest') {
    state.draft = ['안녕하세요! 반가워요.', '오늘 하루는 어떠셨어요?', '퇴근하셨나요?'][Number(arg)];
    render();
  } else if (cmd === 'send') sendMessage();
});

root.addEventListener('input', (e) => {
  if (e.target.id === 'chat-input') state.draft = e.target.value;
});
root.addEventListener('keydown', (e) => {
  if (e.target.id === 'chat-input' && e.key === 'Enter' && !e.isComposing) sendMessage();
});

render();
